{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABlE snitch_db.maplemonk.inventory_health_warehouse as WITH base_raw AS ( SELECT CASE WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'SN%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item SkuCode\")) WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+\'))) WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(\"Item SkuCode\")) END END AS sku_group, UPPER(TRIM(facility)) AS facility, inventory, UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) AS size_token FROM snitch_db.maplemonk.unicommerce_live_inventory ), base AS ( SELECT sku_group, SUM(CASE WHEN size_token = \'XS\' THEN inventory ELSE 0 END) AS XS, SUM(CASE WHEN size_token = \'S\' THEN inventory ELSE 0 END) AS S, SUM(CASE WHEN size_token = \'M\' THEN inventory ELSE 0 END) AS M, SUM(CASE WHEN size_token = \'L\' THEN inventory ELSE 0 END) AS L, SUM(CASE WHEN size_token = \'XL\' THEN inventory ELSE 0 END) AS XL, SUM(CASE WHEN size_token IN (\'2XL\',\'XXL\') THEN inventory ELSE 0 END) AS \"2XL\", SUM(CASE WHEN size_token IN (\'3XL\',\'XXXL\') THEN inventory ELSE 0 END) AS \"3XL\", SUM(CASE WHEN size_token = \'4XL\' THEN inventory ELSE 0 END) AS \"4XL\", SUM(CASE WHEN size_token = \'5XL\' THEN inventory ELSE 0 END) AS \"5XL\", SUM(CASE WHEN size_token = \'6XL\' THEN inventory ELSE 0 END) AS \"6XL\", MAX(CASE WHEN facility = \'SAPL-NORTH-TAURU\' THEN 1 ELSE 0 END) AS has_north, MAX(CASE WHEN facility IN (\'SAPL-WH1\',\'SAPL-WH2\') THEN 1 ELSE 0 END) AS has_south FROM base_raw GROUP BY 1 ), meta_data AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, UPPER(TRIM(l1_category)) AS l1_category, CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%SFS%\' THEN \'SHIRTS\' WHEN UPPER(TRIM(category)) = \'OVERSHIRT\' THEN \'OVERSHIRTS\' ELSE UPPER(TRIM(category)) END AS category, meta1, meta2, meta3 FROM snitch_db.maplemonk.meta_mapping_cogs_sku WHERE LOWER(TRIM(category)) NOT IN (\'(nil)\',\'default\',\'innerwear\') ), ageing as ( select distinct CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+-[^-]+\'))) ELSE UPPER(TRIM(COALESCE( REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+\',1,1), \"Item Type skuCode\"::STRING ))) END AS sku_group, min(putaway_completed_date) as start_date, current_date()- start_date as ageing from snitch_db.maplemonk.putaway_tracking group by 1 ), eoss_bf as ( select sku_group, eoss, bf from snitch_db.maplemonk.eoss_bf ), sales as ( SELECT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, SUM(CASE WHEN UPPER(TRIM(type)) = \'STORE\' THEN gross_quantity ELSE 0 END) AS offline_sales_qty, SUM(CASE WHEN UPPER(TRIM(type)) = \'MARKETPLACE\' THEN gross_quantity ELSE 0 END) AS mp_sales_qty, SUM(CASE WHEN UPPER(TRIM(type)) NOT IN (\'STORE\',\'MARKETPLACE\') THEN gross_quantity ELSE 0 END) AS shopify_sales_qty, SUM(CASE WHEN UPPER(TRIM(type)) = \'STORE\' THEN gross_sales ELSE 0 END) AS offline_sales_value, SUM(CASE WHEN UPPER(TRIM(type)) = \'MARKETPLACE\' THEN gross_sales ELSE 0 END) AS mp_sales_value, SUM(CASE WHEN UPPER(TRIM(type)) NOT IN (\'STORE\',\'MARKETPLACE\') THEN gross_sales ELSE 0 END) AS shopify_sales_value, SUM(CASE WHEN date >= CURRENT_DATE - 30 THEN gross_quantity ELSE 0 END) / 30.0 AS total_ros_l30 FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1 ), final_base AS ( SELECT b.sku_group, md.l1_category, md.category, md.meta1, md.meta2, md.meta3, a.ageing, CASE WHEN b.has_north = 1 AND b.has_south = 1 THEN \'both\' WHEN b.has_north = 1 AND b.has_south = 0 THEN \'north\' WHEN b.has_north = 0 AND b.has_south = 1 THEN \'south\' ELSE NULL END AS warehouse_name, b.XS, b.S, b.M, b.L, b.XL, b.\"2XL\", b.\"3XL\", b.\"4XL\", b.\"5XL\", b.\"6XL\", eb.eoss, eb.bf, s.shopify_sales_qty, s.mp_sales_qty, s.offline_sales_qty, s.shopify_sales_value, s.mp_sales_value, s.offline_sales_value, s.total_ros_l30 FROM base b LEFT JOIN meta_data md ON b.sku_group = md.sku_group left join ageing a on b.sku_group = a.sku_group left join sales s on b.sku_group = s.sku_group left join eoss_bf eb on b.sku_group = eb.sku_group ), calc AS ( SELECT a.*, CASE WHEN a.sku_group LIKE \'%4MBG%\' THEN GREATEST( LEAST( ROUND((COALESCE(a.\"3XL\",0) - 1) / 3), ROUND((COALESCE(a.\"4XL\",0) - 1) / 3), ROUND((COALESCE(a.\"5XL\",0) - 1) / 2), ROUND((COALESCE(a.\"6XL\",0) - 1) / 2) ), 0 ) ELSE GREATEST( LEAST( ROUND((COALESCE(a.S,0) - 2) / 2), ROUND((COALESCE(a.M,0) - 2) / 4), ROUND((COALESCE(a.L,0) - 2) / 4), ROUND((COALESCE(a.XL,0) - 2) / 2) ), 0 ) END AS full_size_options, COALESCE(a.XS,0) + COALESCE(a.S,0) + COALESCE(a.M,0) + COALESCE(a.L,0) + COALESCE(a.XL,0) + COALESCE(a.\"2XL\",0) + COALESCE(a.\"3XL\",0) + COALESCE(a.\"4XL\",0) + COALESCE(a.\"5XL\",0) + COALESCE(a.\"6XL\",0) AS total_inv FROM final_base a ) SELECT sku_group, l1_category, category, meta1, meta2, meta3, eoss, bf, ageing, total_inv as current_inventory, warehouse_name, XS, S, M, L, XL, \"2XL\", \"3XL\", \"4XL\", \"5XL\", \"6XL\", full_size_options, CASE WHEN full_size_options >= 1 THEN \'full_size\' ELSE \'cut_size\' END AS size_flag, CASE WHEN sku_group LIKE \'%4MBG%\' THEN full_size_options * 10 ELSE full_size_options * 12 END AS full_size_inv, shopify_sales_qty, mp_sales_qty, offline_sales_qty, shopify_sales_value, mp_sales_value, offline_sales_value, round(total_ros_l30,2) as ROS_L30 FROM calc;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            